const wsUrl = 'ws://localhost:8080'
const name = 'frontend'
const to = 'backend'
let mid = 0
const wait = new Map()
let ws

const listeners = new Set()

function connect() {
  try {
    if (typeof window === 'undefined' || !window.WebSocket) return;
    
    ws = new window.WebSocket(wsUrl)

    ws.onopen = () => {
      console.log('io module: ✅ Connected to', wsUrl)
    }

    ws.onclose = () => {
      console.log('io module: ❌ Disconnected — retrying in 2s...')
      setTimeout(connect, 2000)
    }

    ws.onerror = (err) => {
      console.error('io module: ⚠️ WebSocket error:', err)
    }

    ws.onmessage = (ev) => {
      const m = JSON.parse(ev.data)
      const key = m.head ? m.head.join(',') : null
      
      if (key && wait.has(key)) {
        const handler = wait.get(key)
        wait.delete(key)
        if (typeof handler === 'function') {
          handler(m)
        }
      }

      for (const listener of listeners) {
        if (typeof listener === 'function') {
          listener(m)
        }
      }
    }
  } catch (err) {
    console.error('io module connect error:', err);
  }
}

// Start connection on import
connect()

function send(type, data, handler) {
  if (!ws || ws.readyState !== window.WebSocket.OPEN) {
    console.warn(`io module: WebSocket not ready for ${type} (Status: ${ws ? ws.readyState : 'null'})`)
    if (handler) handler({ error: 'WebSocket not ready' });
    return
  }
  const head = [name, to, mid++]
  const msg = { head, type, data }
  
  if (handler) {
    const expectedKey = ['backend', name, head[2]].join(',')
    wait.set(expectedKey, handler)
  }
  
  ws.send(JSON.stringify(msg))
}

function listen(handler) {
  listeners.add(handler)
  return () => { listeners.delete(handler) }
}

module.exports = {
  send: send,
  listen: listen,
  get status() { return ws ? ws.readyState : null },
  OPEN: typeof window !== 'undefined' && window.WebSocket ? window.WebSocket.OPEN : 1
}

// ============ Fallback Setup for STATE ============
function fallback_module () {
  return {
    api: fallback_instance
  }
  function fallback_instance (opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return {
      drive: { 
        'data/': { 
          'opts.json': { 
            raw: opts || {} 
          } 
        } 
      },
      _: {}
    }
  }
}
